	row := db.QueryRow(`SELECT name FROM sqlite_master WHERE type='table' AND name='links'`)
	var name string
	if err := row.Scan(&name); err != nil {
		t.Fatalf("links table not found: %v", err)
	}
	if name != "links" {
		t.Fatalf("expected table 'links', got %q", name)
	}
